    rev = 0
    if sales_data:
        units = sum(r.get('cnt', 0) for r in sales_data['rows'] if r.get('metric_key') == 'units_sold')
    if revenue_data:
        rev = sum(r.get('cnt', 0) for r in revenue_data['rows'] if r.get('metric_key') == 'revenue')
